  rreg HR'0 2%bv J2; rreg HR'0 9%bv J9; rreg HR'0 10%bv J10; rreg HR'0 11%bv J11; rreg HR'0 18%bv J18;
  rreg HR'0 19%bv J19; rreg HR'0 22%bv J22; rreg HR'0 24%bv J24;
  lazymatch type of HR'0 with regs_ok _ _ ?RR =>
    assert (GKx : forall r, In r [3; 4; 8; 27]%bv -> getr RR r = getr R1 r) by
      (intros r Hr; eapply (syms_id_sound R1 _ _ _ [3; 4; 8; 27]%bv HR'0); [vm_cast_no_check (@eq_refl bool true) | exact Hr]) end;
  eapply KC; [exact Hms0 | exact Hlf0 | exact J2 | rewrite GKx by inb; reflexivity | rewrite GKx by inb; reflexivity
             | rewrite GKx by inb; reflexivity | rewrite J9; wfix | exact J10 | rewrite J11; G11tac | exact J18 | exact J19
             | exact J22 | exact J24 | rewrite GKx by inb; reflexivity].

Definition sto_frame (m : mem) (spf : Z) (ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 : word) : Prop :=
  rw_cells asegs m spf [C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

Section NtLoop.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.

  Fixpoint nodes_okN (LB : list block) (m : mem) (ns : list (Z * list byte)) : Prop :=
    match ns with
    | [] => True
    | (q, tl) :: ns' =>
        (exists id, In (id, q, 32) LB) /\ rw_cells asegs m q [C8 (Z_to_bv 64 (match ns' with [] => 0 | (q', _) :: _ => q' end)); CB 24 tl]
        /\ addressable m q 32 /\ nodes_okN LB m ns'
    end.

  Lemma ntm_loop_step : forall (Q : config -> Prop)
      (x1 x3 x4 x5 x6 x7 x8 x9 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 x23 x24 x26 x25 x27 x28 x29 x30 x31 : word)
      (F : bvmap 5 word) (fc : bv 32) (msF : machine_state) (m : mem) (s : as_St H) (LB : list block)
      (q : Z) (tl : list byte) (ns : list (Z * list byte)) (spf lo B : Z) (errv : word) (mo : Model) (id : bptr),
    as_VIS H s msF = MS (mkR x1 (Z_to_bv 64 spf) x3 x4 x5 x6 x7 x8 x9 (Z_to_bv 64 q) x11 x12 x13 x14 x15 x16 x17 x18 x19 x20
                             x21 (Z_to_bv 64 0x7fff8000) x23 x24 x25 x26 x27 x28 x29 x30 x31)
                        F (Z_to_bv 64 NT_LOOP) fc None m (seg_rom asegs) ->
    In (id, q, 32) LB ->
    rw_cells asegs m q [C8 (Z_to_bv 64 (match ns with [] => 0 | (q', _) :: _ => q' end)); CB 24 tl] ->
    addressable m q 32 ->
    as_RHEAP H s LB m -> as_AKREL H s (mkCfg msF mo) -> as_Cf H 32 <= as_AL H s ->
    as_rauxv_ok H m B -> spf <= B ->
    stk asegs m lo spf -> aceil <= lo -> lo <= spf - AFREE_STACK ->
    rw_cells asegs m (errno_addr x4) [C4 errv] -> mem_inv asegs m -> x4 = Z_to_bv 64 ATP ->
    spf mod 16 = 0 -> 2 ^ 45 <= spf <= 2 ^ 47 -> ACONST m ->
    (bv_unsigned x8 <= aceil \/ bv_unsigned x8 mod 8 <> 0) ->
    trace_ok (as_TR H) APC0_FREE [NT_DRET1] ->
    (match ns with [] => True | (q', _) :: _ => 0x6e6000 <= q' < 2 ^ 47 end) ->
    (forall (msF' : machine_state) (mo' : Model) (m' : mem) (s' : as_St H) (t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word),
       as_VIS H s' msF' = MS (mkR (Z_to_bv 64 NT_DRET1) (Z_to_bv 64 spf) x3 x4 t0 t1 t2 x8 x9
                                 (Z_to_bv 64 (match ns with [] => 0 | (q', _) :: _ => q' end)) a1 a2 a3 a4 a5 a6 a7 x18 x19 x20
                                 x21 (Z_to_bv 64 0x7fff8000) x23 x24
                                 x25 (Z_to_bv 64 (match ns with [] => 0 | (q', _) :: _ => q' end)) x27 t3 t4 t5 t6)
                             F (Z_to_bv 64 (match ns with [] => NT_L2 | _ => NT_LOOP end)) fc None m' (seg_rom asegs) ->
       as_AKREL H s' (mkCfg msF' mo') -> as_MPRES H mo mo' ->
       mem_inv asegs m' -> stk asegs m' lo spf -> rw_cells asegs m' (errno_addr x4) [C4 errv] -> as_rauxv_ok H m' B ->
       apres H (as_lb_remove H id LB) spf m m' -> as_RHEAP H s' (as_lb_remove H id LB) m' -> ACONST m' ->
       as_AL H s' >= as_AL H s - as_Cf H 32 ->
       as_SR H Q (mkCfg msF' mo')) ->
    as_SR H Q (mkCfg msF mo).
Proof.
