  Lemma ntm_t2c : forall (bl2 bc2 p k : Z) (v : Z * Z * Z) (ents2' : list (Z * (Z * (Z * Z * Z)))) (LB LBs2 : list block)
      (R3 : bvmap 5 word) (F1 : bvmap 5 word) (msF3 : machine_state) (mo3 : Model) (m3 : mem) (s : as_St H) (pad1 pad2 : list byte),
    rfull R3 ->
    as_VIS H s msF3 = MS R3 F1 (Z_to_bv 64 NT_C2) fc None m3 (seg_rom asegs) ->
    as_AKREL H s (mkCfg msF3 mo3) -> as_MPRES H mo0 mo3 ->
    getr R3 2 = Z_to_bv 64 (spz - 96) -> getr R3 3 = gp -> getr R3 4 = tp -> getr R3 8 = Z_to_bv 64 st1 ->
    getr R3 9 = Z_to_bv 64 st2 -> getr R3 10 = rO o2 16 -> getr R3 11 = Z_to_bv 64 (hmod k bc2) -> getr R3 18 = rO o1 16 ->
    getr R3 19 = Z_to_bv 64 o1 -> getr R3 22 = Z_to_bv 64 2147450880 -> getr R3 24 = rSh (Z_to_bv 64 o1) -> getr R3 27 = s11 ->
    TSN s LB bl2 bc2 ((p, (k, v)) :: ents2') LBs2 m3 -> Permutation LB (LB0 ++ LBs2) -> as_AL H s >= as_AL H st0 ->
    hdr40 m3 o1 (Z_to_bv 64 bl2) (Z_to_bv 64 bc2) (Z_to_bv 64 p) (Z_to_bv 64 (Zlength ((p, (k, v)) :: ents2'))) (Z_to_bv 64 0x3f800000) pad1 ->
    hdr40 m3 o2 (Z_to_bv 64 0) (Z_to_bv 64 0) (Z_to_bv 64 p) (Z_to_bv 64 (Zlength ((p, (k, v)) :: ents2'))) (Z_to_bv 64 0x3f800000) pad2 ->
    umapx MI_A 32 (nval32 ASEGS) (lbl LBs2) m0 o2 bl2 bc2 ((p, (k, v)) :: ents2') ->
    Permutation (lbl LBs2) (umap_blocks 32 bl2 bc2 ((p, (k, v)) :: ents2')) ->
    (forall b, In b LBs2 -> apart o1 40 (blk_addr b) (blk_size b)) ->
