  Lemma ntm_t2 : forall (bl2 bc1 bc2 : Z) (ents2 : list (Z * (Z * (Z * Z * Z)))) (LB LBs2 : list block)
      (x1 x5 x6 x7 x10 x11 x12 x13 x14 x15 x16 x17 x25 x26 x28 x29 x30 x31 : word)
