  Fixpoint nodes_okAN (LBn : list block) (m : mem) (ns : list (Z * list byte)) : Prop :=
    match LBn, ns with
    | [], [] => True
    | b :: LBn', (q, tl) :: ns' =>
        blk_addr b = q /\ blk_size b = 32
        /\ rw_cells asegs m q [C8 (Z_to_bv 64 (match ns' with [] => 0 | (q', _) :: _ => q' end)); CB 24 tl]
        /\ addressable m q 32
        /\ (match ns' with [] => True | (q', _) :: _ => 0x6e6000 <= q' < 2 ^ 47 end)
        /\ nodes_okAN LBn' m ns'
    | _, _ => False
    end.

  Lemma nodes_okAN_apres : forall LBn ns LB' SP m m',
    nodes_okAN LBn m ns -> apres H LB' SP m m' -> (forall b, In b LBn -> In b LB') -> nodes_okAN LBn m' ns.
Proof.
