  Lemma hdr40_of_hdrN : forall M o bl bc (ents : list (Z * (Z * (Z * Z * Z)))),
    HRep.hdr ASEGS M o bl bc ents -> AIMG_TOP <= o -> o + 40 <= 2 ^ 47 ->
    exists pad, hdr40 M o (Z_to_bv 64 bl) (Z_to_bv 64 bc) (Z_to_bv 64 (hdaddr ents)) (Z_to_bv 64 (Zlength ents)) (Z_to_bv 64 0x3f800000) pad.
Proof.
